public static void main(String[] args)
{
    FastReader sc = new FastReader();
    PrintWriter out=new PrintWriter(System.out);
    int n=sc.nextInt();
    int[] arr=new int[2*n];
    for(int i=0;i<2*n;++i) arr[i]=sc.nextInt(); // Corrected to read 2*n values

    // Create a map to store the positions of each color
    Map<Integer, List<Integer>> colorPositions = new HashMap<>();
    for (int i = 0; i < 2 * n; i++) {
        colorPositions.putIfAbsent(arr[i], new ArrayList<>());
        colorPositions.get(arr[i]).add(i);
    }

    int c = 0;
    // Check the condition for each color
    for (int color = 1; color <= n; color++) {
        List<Integer> positions = colorPositions.get(color);
        if (positions.size() == 2 && positions.get(1) - positions.get(0) == 2) {
            c++;
        }
    }

    out.println(c);
    out.flush();
}

